import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiSkills","description":"","frontmatter":{},"headers":[],"relativePath":"modules/skills/index.md","filePath":"modules/skills/index.md","lastUpdated":0}`),a={name:`modules/skills/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakiskills" tabindex="-1">EmakiSkills <a class="header-anchor" href="#emakiskills" aria-label="Permalink to “EmakiSkills”">​</a></h1><p>EmakiSkills 是玩家技能管理模块，负责技能解锁、主动技能槽位、被动触发器、施法模式、冷却、资源消耗、升级和玩家档案，即“什么时候允许释放、消耗什么、谁触发”。</p><p>技能效果本身有两条执行路径，由 <code>script.mode</code> 选择：<code>native</code> 走内置脚本系统（<code>script_engine.default_mode</code> 默认就是 <code>native</code>，不需要任何外部插件），<code>mythic</code> 交给 MythicMobs 执行，<code>hybrid</code> 两者都执行。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>2.8.1</code></td></tr><tr><td>Jar 名</td><td><code>EmakiSkills-2.8.1.jar</code></td></tr><tr><td>Maven 坐标</td><td><code>emaki.jiuwu.craft:emaki-skills:2.8.1</code></td></tr><tr><td>API 坐标</td><td><code>emaki.jiuwu.craft:emaki-skills-api:2.8.1</code></td></tr><tr><td>平台</td><td>Paper <code>1.21.8</code>（<code>api-version: &quot;1.21.8&quot;</code>，<code>folia-supported: true</code>）</td></tr><tr><td>主命令</td><td><code>/emakiskills</code></td></tr><tr><td>别名</td><td><code>/eskills</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>MythicMobs、EmakiAttribute、PlaceholderAPI、AuraSkills、MythicLib、MMOCore</td></tr><tr><td>主要权限</td><td><code>emakiskills.use</code>、<code>emakiskills.reload</code>、<code>emakiskills.admin</code>、<code>emakiskills.debug</code></td></tr></tbody></table><h2 id="模块分工" tabindex="-1">模块分工 <a class="header-anchor" href="#模块分工" aria-label="Permalink to “模块分工”">​</a></h2><table tabindex="0"><thead><tr><th>模块 / 插件</th><th>职责</th></tr></thead><tbody><tr><td>EmakiSkills</td><td>技能定义、槽位、触发器、冷却、资源、升级、玩家数据。</td></tr><tr><td>MythicMobs</td><td>执行真正的技能效果，例如伤害、粒子、召唤、位移。</td></tr><tr><td>EmakiAttribute</td><td>提供属性检查、资源检查和资源消耗。</td></tr><tr><td>EmakiItem</td><td>物品可提供技能解锁、触发器或套装技能。</td></tr><tr><td>PlaceholderAPI</td><td>展示技能状态、冷却、等级等信息。</td></tr></tbody></table><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to “默认配置目录”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiSkills/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── skills/</span></span>
<span class="line"><span>├── resources/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   ├── skills_gui.yml</span></span>
<span class="line"><span>│   ├── trigger_select_gui.yml</span></span>
<span class="line"><span>│   └── upgrade_gui.yml</span></span>
<span class="line"><span>├── data/</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><h2 id="config-yml-顶层键" tabindex="-1">config.yml 顶层键 <a class="header-anchor" href="#config-yml-顶层键" aria-label="Permalink to “config.yml 顶层键”">​</a></h2><p><code>config.yml</code> 顶层只有版本、语言与默认数据释放三个开关，以及 <code>slots</code> 块。其余键分布在功能页中。</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># version 由资源同步维护，不是功能开关。</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.8.1&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 语言文件名，对应 lang/&lt;language&gt;.yml。</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">language</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;zh_CN&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 是否在启动时释放插件内置的默认技能数据。</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">release_default_data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 默认技能槽数量；小于 1 的值会按 1 处理。</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  default_count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>默认值</th><th>取值范围</th><th>说明</th></tr></thead><tbody><tr><td><code>version</code></td><td>string</td><td>否</td><td><code>&quot;2.8.1&quot;</code></td><td>—</td><td>资源版本号，由资源同步流程维护，不参与功能开关。</td></tr><tr><td><code>language</code></td><td>string</td><td>否</td><td><code>&quot;zh_CN&quot;</code></td><td><code>lang/</code> 下的文件名（不含 <code>.yml</code>）</td><td>加载 <code>lang/&lt;language&gt;.yml</code> 作为玩家可见文案来源。</td></tr><tr><td><code>release_default_data</code></td><td>boolean</td><td>否</td><td><code>true</code></td><td><code>true</code> / <code>false</code></td><td>启动时是否释放插件内置的默认技能数据（示例技能等）。</td></tr><tr><td><code>slots.default_count</code></td><td>integer</td><td>否</td><td><code>3</code></td><td>≥ 1，小于 1 按 1</td><td>玩家默认技能槽数量；决定 ActionBar 的 <code>%slot_1%</code>~<code>%slot_n%</code> 数量与占位符 <code>%emakiskills_slot_count%</code> 的基准值。</td></tr></tbody></table><p>键的归属：</p><table tabindex="0"><thead><tr><th>键</th><th>记录页面</th></tr></thead><tbody><tr><td><code>skill_sources.*</code>、<code>skill_tags.equip_limits</code></td><td><a href="./definitions.html">技能定义</a></td></tr><tr><td><code>triggers</code>、<code>passive_triggers</code>、<code>trigger_settings</code>、<code>passive_trigger_settings</code>、<code>cast_mode</code></td><td><a href="./triggers.html">触发器</a></td></tr><tr><td><code>actionbar</code>、<code>cast_timing</code></td><td><a href="./actionbar.html">技能状态栏</a></td></tr><tr><td><code>script_engine</code></td><td><a href="./script.html">原生脚本系统</a></td></tr></tbody></table><div class="note custom-block"><p class="custom-block-title">配置预检</p><p>加载时会检查 <code>config.yml</code>、<code>skills/</code>、<code>resources/</code>、<code>gui/</code> 是否存在并可解析，并对脚本动作行做编译期校验。<code>skill_sources</code> 两侧都关闭、或 <code>require_lore_pdc_match</code> 开启但只开启了一侧时，会给出警告。</p></div><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>GUI、施法模式、等级管理、槽位清理和调试命令。</td></tr><tr><td><a href="./definitions.html">技能定义</a></td><td>主动/被动技能、资源消耗、升级和配置字段。</td></tr><tr><td><a href="./triggers.html">触发器</a></td><td>主动触发器、被动触发器、冲突和连击配置。</td></tr><tr><td><a href="./parameters.html">变量类型</a></td><td>变量类型、字段和运行时解析。</td></tr><tr><td><a href="./script.html">原生脚本系统</a></td><td>脚本模式、阶段、动作、限制和目标解析。</td></tr><tr><td><a href="./actionbar.html">技能状态栏</a></td><td>Action Bar 模板、刷新间隔和施法模式提示。</td></tr><tr><td><a href="./placeholders.html">占位符</a></td><td>PlaceholderAPI 输出。</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>技能释放、等级、槽位、冷却和手动解锁动作。</td></tr><tr><td><a href="./api.html">API</a></td><td>技能 API 与外部技能来源扩展。</td></tr><tr><td><a href="./events.html">事件 API</a></td><td>技能流程的 Bukkit 事件与拦截点。</td></tr></tbody></table><h2 id="技能类型" tabindex="-1">技能类型 <a class="header-anchor" href="#技能类型" aria-label="Permalink to “技能类型”">​</a></h2><h3 id="主动技能" tabindex="-1">主动技能 <a class="header-anchor" href="#主动技能" aria-label="Permalink to “主动技能”">​</a></h3><p>主动技能通常由玩家手动释放，例如通过技能槽、命令、GUI 或施法模式。主动技能常见配置：</p><ul><li>MythicMobs 技能 ID。</li><li>冷却时间。</li><li>全局冷却。</li><li>资源消耗。</li><li>条件检查。</li><li>技能等级和参数。</li></ul><h3 id="被动技能" tabindex="-1">被动技能 <a class="header-anchor" href="#被动技能" aria-label="Permalink to “被动技能”">​</a></h3><p>被动技能由事件触发，例如攻击、受击、击杀、移动、格挡等。被动技能需要配置触发器和冲突处理方式。</p><h2 id="施法模式" tabindex="-1">施法模式 <a class="header-anchor" href="#施法模式" aria-label="Permalink to “施法模式”">​</a></h2><p>施法模式用于让玩家在特定状态下选择或释放技能。当前服务端无法原生监听客户端 G 键这类本地按键，因此技能触发通常依赖服务端可见行为，例如命令、GUI、F 键交换手、交互事件等。</p><h2 id="资源系统" tabindex="-1">资源系统 <a class="header-anchor" href="#资源系统" aria-label="Permalink to “资源系统”">​</a></h2><p>技能可以消耗或检查多种资源：</p><ul><li><code>ea-resource</code>：通过 EmakiAttribute Bridge 消耗 Attribute 资源。</li><li><code>attribute-check</code>：检查某个属性是否达到要求。别名 <code>ea-attribute-check</code>。</li><li><code>local-resource</code>：使用 EmakiSkills 本地资源定义。</li><li><code>auraskills-mana</code>：使用 AuraSkills 的法力值。别名 <code>aura-skills-mana</code>、<code>aura-mana</code>。</li><li><code>mythiclib-mana</code>：使用 MythicLib / MMOCore 的法力值。别名 <code>mmocore-mana</code>、<code>mythic-mana</code>。</li></ul><h2 id="典型释放流程" tabindex="-1">典型释放流程 <a class="header-anchor" href="#典型释放流程" aria-label="Permalink to “典型释放流程”">​</a></h2><ol><li>玩家触发主动或被动技能。</li><li>Skills 检查玩家是否拥有该技能。</li><li>检查技能等级、槽位、触发器和条件。</li><li>检查冷却和全局冷却。</li><li>检查并消耗资源。</li><li>按 <code>script.mode</code> 执行内置脚本动作、MythicMobs 技能，或两者。</li><li>写入冷却、统计或升级进度。</li><li>向玩家发送反馈。</li></ol><p>玩家可见的失败反馈来自 <code>lang/&lt;language&gt;.yml</code> 的 <code>cast.*</code> 等文案键，不会把内部 reasonKey 直接输出给玩家。</p>`,32)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};